-- Year 6 question bank clean-up (data only).
--
-- 1. Worked solutions that showed the AI answer-checker's notes to students
--    ("…matching option B, not the marked option A"). The checker used to
--    overwrite a question's solution with its own note when it corrected the
--    answer key; lib/verify-question.ts now stores a student-facing solution or
--    drops the question. The keys on these were already right: only the
--    solution text changes.
-- 2. Broken questions: two correct options (q06msi, dek2hd, uj10ux, igmfax),
--    duplicate options (geyyh4, e9pxcp, nsold5), a wrong answer key (46eyxn),
--    a wrong key and muddled grammar (9yxe0r), and ambiguous wording (io1yys,
--    wkewhp, wld6p8, i0cdnf).
--
-- Every row is copied to backup.questions_fix_20261026 first (not exposed to
-- the API), so a change can be undone with an update from that table. Safe to
-- run twice.

create schema if not exists backup;
revoke all on schema backup from public, anon, authenticated;
create table if not exists backup.questions_fix_20261026 as select * from public.questions where false;
insert into backup.questions_fix_20261026 select * from public.questions where id in ('ai_1792046023044_7m14lt','ai_1792046062834_9yxe0r','ai_1792046088830_22prhm','ai_1792046214138_xx18yc','ai_1792046245175_e9pxcp','ai_1792373727340_y690dn','ai_1792373727341_npsvb1','ai_1792373727341_zp8dla','ai_1792373727342_429tva','ai_1792373746556_l8ii9g','ai_1792373868604_2yw1tm','ai_1792373905934_uj10ux','ai_1792373923200_7a5qr3','ai_1792373923200_9pk9o9','ai_1792374004031_3q8ggc','ai_1792374047588_hjwz6v','ai_1792374083695_f1zz4l','ai_1792374106445_uuxbxf','ai_1792374106445_y1yvu0','ai_1792374143415_qapla3','ai_1792374161527_yewo43','ai_1792374180041_2yae9d','ai_1792374180042_8p9ium','ai_1792374258196_6308xf','ai_1792374258196_i0cdnf','ai_1792374258196_ksn326','ai_1792374258196_q06msi','ai_1792374396742_io1yys','ai_1792374414866_23pqrh','ai_1792374414866_5y246d','ai_1792374414866_byo42w','ai_1792374449802_fpvo4t','ai_1792374523624_4j6te3','ai_1792374566708_dw5snm','ai_1792374611383_geyyh4','ai_1792374651387_hkbex5','ai_1792374689361_mfx3kd','ai_1792374717060_wld6p8','ai_1792374733199_1kavhu','ai_1792374733199_8srjfq','ai_1792375327737_rrdnik','ai_1792375327738_38xwo8','ai_1792375327738_95e5xb','ai_1792375327738_cjqzfk','ai_1792375327738_f3hif7','ai_1792380402745_nsold5','ai_1792380491259_igmfax','ai_1792384325272_njvuph','ai_1792384370143_dek2hd','ai_1792400648031_idpwyu','ai_1792400648032_sfd9zq','ai_1792400648033_8po3ki','ai_1792400648033_laa616','ai_1792400648033_y7brux','ai_1792401978410_eotdg1','ai_1792401978411_fye3ki','ai_1792402739721_jxc34a','ai_1792620212013_46eyxn','ai_1792620230025_dswiqq','ai_1792620230026_wkewhp') and id not in (select id from backup.questions_fix_20261026);
