update public.questions set solution = $F$After a $35\%$ increase the coin is worth $135\%$ of its starting value, so divide by $1.35$: $81.90 \div 1.35 = 60.666\ldots$, which rounds to $£60.67$.$F$ where id = 'ai_1792374004031_3q8ggc';
